import { ChangeDetectionStrategy, Component } from '@angular/core';
import { SupplierService } from '../../services/supplier-service';
import {
  FormGroup,
  FormControl,
  FormBuilder,
  Validators,
  ReactiveFormsModule,
} from '@angular/forms';
import { Authservice } from '../../services/authservice';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';

@Component({
  selector: 'app-add-supplier',
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './add-supplier.html',
  styleUrl: './add-supplier.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AddSupplier {
  supplierForm: FormGroup;
  stateControl = new FormControl('');

  States = [
    { id: 1, name: 'JAMMU AND KASHMIR' },
    { id: 2, name: 'HIMACHAL PRADESH' },
    { id: 3, name: 'PUNJAB' },
    { id: 4, name: 'CHANDIGARH' },
    { id: 5, name: 'UTTARAKHAND' },
    { id: 6, name: 'HARYANA' },
    { id: 7, name: 'DELHI' },
    { id: 8, name: 'RAJASTHAN' },
    { id: 9, name: 'UTTAR PRADESH' },
    { id: 10, name: 'BIHAR' },
    { id: 11, name: 'SIKKIM' },
    { id: 12, name: 'ARUNACHAL PRADESH' },
    { id: 13, name: 'NAGALAND' },
    { id: 14, name: 'MANIPUR' },
    { id: 15, name: 'MIZORAM' },
    { id: 16, name: 'TRIPURA' },
    { id: 17, name: 'MEGHLAYA' },
    { id: 18, name: 'ASSAM' },
    { id: 19, name: 'WEST BENGAL' },
    { id: 20, name: 'JHARKHAND' },
    { id: 21, name: 'ODISHA' },
    { id: 22, name: 'CHATTISGARH' },
    { id: 23, name: 'MADHYA PRADESH' },
    { id: 24, name: 'GUJARAT' },
    { id: 26, name: 'DADRA AND NAGAR HAVELI AND DAMAN AND DIU' },
    { id: 27, name: 'MAHARASHTRA' },
    { id: 28, name: 'ANDHRA PRADESH(BEFORE DIVISION)' },
    { id: 29, name: 'KARNATAKA' },
    { id: 30, name: 'GOA' },
    { id: 31, name: 'LAKSHWADEEP' },
    { id: 32, name: 'KERALA' },
    { id: 33, name: 'TAMIL NADU' },
    { id: 34, name: 'PUDUCHERRY' },
    { id: 35, name: 'ANDAMAN AND NICOBAR ISLANDS' },
    { id: 36, name: 'TELANGANA' },
    { id: 37, name: 'ANDHRA PRADESH (NEWLY ADDED)' },
    { id: 38, name: 'LADAKH (NEWLY ADDED)' },
  ];

  constructor(
    private fb: FormBuilder,
    private service: SupplierService,
    private authService: Authservice,
    private router: Router
  ) {
    this.supplierForm = this.fb.group({
      name: ['', Validators.required],
      address: ['', Validators.required],
      GSTIN: ['', Validators.required],
      state: ['', Validators.required],
      stateCode: ['', Validators.required],
      phone: [''],
      email: [''],
    });
  }

  onStateChange(event: Event) {
    const target = event.target as HTMLSelectElement;
    const stateId = Number(target.value);
    const selectedState = this.States.find((s) => s.id === stateId);

    if (selectedState) {
      this.supplierForm.patchValue({
        state: selectedState.name,
        stateCode: selectedState.id,
      });
    }
  }

  onSubmit() {
    console.log('Submit clicked');
    if (this.supplierForm.invalid) {
      this.supplierForm.markAllAsTouched();
      return console.log('Form value invalid', console.error());
    }

    console.log('Form value:', this.supplierForm.value);
    const payload = {
  ...this.supplierForm.value,
  phone: this.supplierForm.value.phone ? String(this.supplierForm.value.phone) : null
};
    console.log('form: ', payload)
    this.service.CreateSupplier(payload).subscribe({
      next: () => {
        alert('✅ Supplier created successfully');
        this.resetForm();
        this.router.navigate(['/supplier'])
      },
      error: (err) => {
        console.error('❌ Upload failed', err);
        alert(err.error?.message || 'Upload failed. Please try again.');
      },
      
    });
  }

  private resetForm() {
    this.supplierForm.reset();
    this.stateControl.reset();
  }
}
